cast = json.load(open("cast.json", encoding="utf-8"))
n = 0
for c in cast:
    if c["id"] in REDO:
        c.setdefault("character_v1", c["character"])  # (the first go, kept)
        c["character"] = REDO[c["id"]]
        if c["id"] == "merchant_1": c["name"] = "Captain Ambrose Tull"
        n += 1
json.dump(cast, open("cast.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(n, "re-written:", " ".join(REDO))
